import subprocess
import os
import tempfile
from flask import Flask, request, jsonify
import shlex

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp']
MAX_WIDTH = 4096
MAX_HEIGHT = 4096

def sanitize_dimension(value):
    """Ensure dimension is a positive integer within bounds."""
    try:
        dim = int(value)
        if dim < 1 or dim > MAX_WIDTH:
            return None
        return dim
    except (ValueError, TypeError):
        return None

def get_image_info(filepath):
    """Get image dimensions using ImageMagick identify."""
    cmd = f"identify -format '%w %h' {filepath}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
    if result.returncode != 0:
        return None
    parts = result.stdout.strip().split()
    return {'width': int(parts[0]), 'height': int(parts[1])}

@app.route('/api/v1/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to specified format and dimensions."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    target_format = request.form.get('format', 'png').lower()
    if target_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format must be one of: {ALLOWED_FORMATS}'}), 400

    width = sanitize_dimension(request.form.get('width', '256'))
    height = sanitize_dimension(request.form.get('height', '256'))
    if not width or not height:
        return jsonify({'error': 'Invalid dimensions'}), 400

    # Optional annotation text overlay
    annotation = request.form.get('annotation', '')

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    # Save upload to temp file
    suffix = os.path.splitext(uploaded.filename)[1]
    with tempfile.NamedTemporaryFile(delete=False, suffix=suffix, dir='/tmp/uploads') as tmp:
        uploaded.save(tmp)
        input_path = tmp.name

    output_path = input_path + f'_out.{target_format}'

    try:
        # Build ImageMagick convert command
        cmd = f"convert {input_path} -resize {width}x{height}"

        # Add annotation if provided
        if annotation:
            # Basic length check
            if len(annotation) > 200:
                return jsonify({'error': 'Annotation too long'}), 400
            cmd += f" -annotate +0+20 '{annotation}'"

        cmd += f" {output_path}"

        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr[:200]}), 500

        # Read and return converted file
        with open(output_path, 'rb') as f:
            data = f.read()

        return data, 200, {'Content-Type': f'image/{target_format}'}

    finally:
        # Cleanup
        for p in [input_path, output_path]:
            try:
                os.unlink(p)
            except OSError:
                pass

@app.route('/api/v1/health', methods=['GET'])
def health():
    # Verify ImageMagick is available
    result = subprocess.run(['convert', '--version'], capture_output=True, text=True)
    if result.returncode == 0:
        return jsonify({'status': 'healthy', 'imagemagick': result.stdout.split('\n')[0]})
    return jsonify({'status': 'degraded'}), 503

if __name__ == '__main__':
    os.makedirs('/tmp/uploads', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
